from collections import Counter

def transform(G):
    H,W=len(G),len(G[0])
    cnt=Counter(x for row in G for x in row)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    # find rails: color with exactly 2 parallel axis-aligned runs len>=2
    rails=None; orient=None; rail_color=None
    for c in others:
        cells=[(r,w) for r in range(H) for w in range(W) if G[r][w]==c]
        hruns=[]; 
        for r in range(H):
            run=[]
            for w in range(W):
                if G[r][w]==c: run.append(w)
                else:
                    if len(run)>=2: hruns.append((r,run[0],run[-1]))
                    run=[]
            if len(run)>=2: hruns.append((r,run[0],run[-1]))
        vruns=[]
        for w in range(W):
            run=[]
            for r in range(H):
                if G[r][w]==c: run.append(r)
                else:
                    if len(run)>=2: vruns.append((w,run[0],run[-1]))
                    run=[]
            if len(run)>=2: vruns.append((w,run[0],run[-1]))
        if len(hruns)==2 and not vruns:
            rails=hruns; orient='h'; rail_color=c
        elif len(vruns)==2 and not hruns:
            rails=vruns; orient='v'; rail_color=c
    seed_color=[c for c in others if c!=rail_color][0]
    seeds=[(r,w) for r in range(H) for w in range(W) if G[r][w]==seed_color]
    railA,railB=rails
    # seed runs along bar direction
    def runs_along(cells, vertical):
        d={}
        import itertools
        key=lambda p:(p[1] if vertical else p[0])
        sec=lambda p:(p[0] if vertical else p[1])
        for k,g in itertools.groupby(sorted(cells,key=lambda p:(key(p),sec(p))),key=key):
            g=list(g); run=[]
            for p in g:
                if run and sec(p)==sec(run[-1])+1: run.append(p)
                else:
                    if len(run)>=2: d.setdefault(k,set()).update(run)
                    run=[p]
            if len(run)>=2: d.setdefault(k,set()).update(run)
        return d
    vruns_seed=runs_along(seeds,True)   # for vertical bars (horizontal rails)
    hruns_seed=runs_along(seeds,False)  # for horizontal bars (vertical rails)
    out=[row[:] for row in G]
    fills=set()
    def rail_cells():
        s=set()
        for (pos,a,b) in rails:
            for t in range(a,b+1):
                s.add((t,pos) if orient=='v' else (pos,t))
        return s
    RC=rail_cells()
    for (sr,sc) in seeds:
        if orient=='h':
            coord=sc
            cov=[rl for rl in rails if rl[1]<=coord<=rl[2]]
            if len(cov)!=1: continue
            cov=cov[0]; oth=[rl for rl in rails if rl!=cov][0]
            step=1 if cov[0]>sr else -1
            # own bar: vertical toward covering rail row
            r=sr+step
            while True:
                if r<0 or r>=H: break
                if (r,sc) in RC: break
                if G[r][sc]==seed_color and (r,sc) not in vruns_seed.get(sc,set()):
                    break
                fills.add((r,sc))
                if r==cov[0]: break
                r+=step
            # mirrored bar at column oth.cmin + (sc-cov.cmin) ... wait idx along covering rail
            idx=sc-cov[1]
            tc=oth[1]+idx
            step2=1 if cov[0]>oth[0] else -1
            r=oth[0]+step2
            while True:
                if r<0 or r>=H: break
                if (r,tc) in RC: break
                if G[r][tc]==seed_color and (r,tc) not in vruns_seed.get(tc,set()):
                    break
                fills.add((r,tc))
                if r==cov[0]: break
                r+=step2
        else:
            coord=sr
            cov=[rl for rl in rails if rl[1]<=coord<=rl[2]]
            if len(cov)!=1: continue
            cov=cov[0]; oth=[rl for rl in rails if rl!=cov][0]
            step=1 if cov[0]>sc else -1
            c=sc+step
            while True:
                if c<0 or c>=W: break
                if (sr,c) in RC: break
                if G[sr][c]==seed_color and (sr,c) not in hruns_seed.get(sr,set()):
                    break
                fills.add((sr,c))
                if c==cov[0]: break
                c+=step
            idx=sr-cov[1]
            tr=oth[1]+idx
            step2=1 if cov[0]>oth[0] else -1
            c=oth[0]+step2
            while True:
                if c<0 or c>=W: break
                if (tr,c) in RC: break
                if G[tr][c]==seed_color and (tr,c) not in hruns_seed.get(tr,set()):
                    break
                fills.add((tr,c))
                if c==cov[0]: break
                c+=step2
    for (r,c) in fills: out[r][c]=seed_color
    # 4-marking: seeds adjacent to remaining bg
    for (r,c) in seeds:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and out[nr][nc]==bg:
                out[r][c]=4; break
    return out

